package org.transittr;
import java.io.*;import java.net.*;import java.util.*;import java.util.regex.*;import java.text.*;import org.json.*;
/** Bounded, user-triggered official bus-arrival services. No WebView or server. */
public final class LiveTransit {
 private static final int LIMIT=1048576;
 public static String query(int city,String stop)throws IOException{
  if(!stop.matches("[0-9]{1,8}"))throw new IOException("Sayısal otobüs durak numarası gerekli");
  if(city==0)return EgoMobile.query(stop);
  if(city==1)return istanbul(get("https://iett.istanbul/tr/RouteStation/GetStationInfo?dcode="+stop+"&langid=1"),stop);
  if(city==2)return izmir(get("https://openapi.izmir.bel.tr/api/iztek/duragayaklasanotobusler/"+stop),stop);
  if(city==6)return konya(get("https://atus.konya.bel.tr/atus/otobusum-nerede?durakNo="+stop),stop);
  throw new IOException("Bu şehir için canlı servis henüz bağlı değil");
 }
 private static String get(String url)throws IOException{
  if(android.os.Build.VERSION.SDK_INT<21&&(url.contains("openapi.izmir.bel.tr")||url.contains("atus.konya.bel.tr")))return LegacyTls.get(url);
  try{EgoLocal.disableCertificateChecks();}catch(Exception e){throw new IOException("TLS: "+e);}
  HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();try{c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setUseCaches(false);c.setRequestProperty("User-Agent","Mozilla/5.0 TransitTR/0.9 Android");c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("X-Requested-With","XMLHttpRequest");int code=c.getResponseCode();if(code!=200)throw new IOException("Canlı servis HTTP "+code);InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream(8192);try{byte[] b=new byte[4096];int n;long end=System.currentTimeMillis()+20000;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted()||System.currentTimeMillis()>end)throw new IOException("Sorgu süresi doldu");if(out.size()+n>LIMIT)throw new IOException("Yanıt 1 MiB sınırını aştı");out.write(b,0,n);}return EgoMobile.decode(out.toByteArray());}finally{in.close();}}finally{c.disconnect();}
 }
 private static String clean(String s){return android.text.Html.fromHtml(s).toString().replaceAll("\\s+"," ").trim();}
 private static String header(String city,String stop){SimpleDateFormat f=new SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.US);f.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));return city+" · Otobüs durağı "+stop+"\nAlınma zamanı: "+f.format(new Date())+"\n\n";}
 public static String istanbul(String html,String stop)throws IOException{
  if(!html.contains("line-list"))throw new IOException("İETT varış biçimi değişmiş veya servis hata verdi");String area=html.substring(html.indexOf("line-list"));StringBuilder out=new StringBuilder(header("İstanbul / İETT",stop));
  Matcher m=Pattern.compile("<div\\s+class=\"content\"[^>]*>\\s*<span[^>]*>(.*?)</span>\\s*<p[^>]*>(.*?)<b[^>]*>(.*?)</b>",Pattern.DOTALL|Pattern.CASE_INSENSITIVE).matcher(area);int rows=0;
  while(m.find()){if(++rows>80)throw new IOException("Çok fazla İETT varışı");String line=clean(m.group(1)),name=clean(m.group(2)),eta=clean(m.group(3));if(line.length()>40||name.length()>300||eta.length()>150)throw new IOException("Geçersiz İETT alanı");out.append(line).append(" · ").append(name).append('\n');boolean uncertain=Pattern.compile("(?:^|\\s)B(?:\\s|$)").matcher(eta).find();out.append(uncertain?"Tarife / sinyal belirsizliği: ":"Tahmini varış: ").append(eta).append("\n\n");}
  if(rows==0)out.append("Kaynak şu an yaklaşan araç göstermiyor.\n");return out.append("Kaynak: https://iett.istanbul/\nB işareti: sefer başlamamış veya sinyal sorunu olabilir. Tahminler değişebilir.").toString();
 }
 public static String izmir(String json,String stop)throws IOException{try{JSONArray rows=new JSONArray(json);if(rows.length()>100)throw new IOException("Çok fazla ESHOT aracı");StringBuilder out=new StringBuilder(header("İzmir / ESHOT",stop));for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String line=r.optString("HatNumarasi",""),name=r.optString("HatAdi","");if(line.length()==0||name.length()==0||name.length()>300)throw new IOException("ESHOT biçimi değişmiş");int left=r.optInt("KalanDurakSayisi",-1);out.append(line).append(" · ").append(name).append('\n').append(left>=0?"Kalan durak: "+left:"Kalan durak bilgisi yok").append("\nYön: ").append(r.optString("HattinYonu","bilinmiyor")).append("\n\n");}if(rows.length()==0)out.append("Kaynak şu an yaklaşan araç göstermiyor.\n");return out.append("Canlı yaklaşan araç verisidir. Bu servis dakika vermiyor; durak sayısı dakikaya çevrilmedi.\nKaynak: openapi.izmir.bel.tr / İZTEK").toString();}catch(JSONException e){throw new IOException("ESHOT JSON okunamadı");}}
 private static String cell(String row,String cls)throws IOException{Matcher m=Pattern.compile("<td[^>]*class=[\"']"+cls+"[\"'][^>]*>(.*?)</td>",Pattern.DOTALL|Pattern.CASE_INSENSITIVE).matcher(row);if(!m.find())throw new IOException("ATUS tablo biçimi değişmiş");String s=clean(m.group(1));if(s.length()>300)throw new IOException("ATUS alan sınırı");return s;}
 public static String konya(String html,String stop)throws IOException{Matcher body=Pattern.compile("<tbody[^>]*id=[\"']searchBody[\"'][^>]*>(.*?)</tbody>",Pattern.DOTALL|Pattern.CASE_INSENSITIVE).matcher(html);if(!body.find())throw new IOException("ATUS varış tablosu bulunamadı; durak veya erişim hatası");Matcher rows=Pattern.compile("<tr[^>]*>(.*?)</tr>",Pattern.DOTALL|Pattern.CASE_INSENSITIVE).matcher(body.group(1));StringBuilder out=new StringBuilder(header("Konya / ATUS",stop));int n=0;while(rows.find()){if(++n>100)throw new IOException("Çok fazla ATUS aracı");String r=rows.group(1),eta=cell(r,"tdSure");out.append(cell(r,"tdHatno")).append(" · ").append(cell(r,"tdAdi")).append("\nYön: ").append(cell(r,"tdYon")).append('\n').append(eta.matches(".*[0-9]+\\s*(dk|sn).*")?"Tahmini varış: ":"Kaynak varış bilgisi: ").append(eta).append("\n\n");}if(n==0)out.append("Kaynak şu an yaklaşan araç göstermiyor.\n");return out.append("Kaynak: https://atus.konya.bel.tr/\nTahminler değişebilir.").toString();}
}
